using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

const string modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. When given a topic:
        1. Use the WebSearch tool to find relevant information (make multiple searches if needed).
        2. Use the TakeNote tool to record key findings as you go.
        3. After gathering enough information, provide a comprehensive summary of your findings.
        Always cite which searches led to your conclusions.
        """,
};

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(tools.WebSearch),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    tools.ClearNotes();

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {input}"),
    };

    var invokeOptions = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        ChatOptions = chatOptions,
    };

    Console.WriteLine("\nResearching...\n");

    await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");

    var notes = tools.GetNotes();
    if (!string.IsNullOrWhiteSpace(notes))
    {
        Console.WriteLine("--- Research Notes ---");
        Console.WriteLine(notes);
        Console.WriteLine("--- End Notes ---\n");
    }

    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

/// <summary>Tools available to the research agent.</summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    [Description("Searches the web for the given query and returns a summary of results. Use this to find information about a topic.")]
    public async Task<string> WebSearch([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");

            var response = await _httpClient.SendAsync(request);
            var html = await response.Content.ReadAsStringAsync();

            var results = ParseSearchResults(html);
            return results.Length > 0
                ? $"Search results for '{query}':\n{results}"
                : $"No results found for '{query}'.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    [Description("Records a research note. Use this to save important findings as you discover them.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
        return $"Note saved. You have {_notes.Count} note(s) recorded.";
    }

    [Description("Retrieves all notes taken during this research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes recorded yet.";

        return string.Join("\n\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    public void ClearNotes() => _notes.Clear();

    private static string ParseSearchResults(string html)
    {
        var results = new List<string>();
        var span = html.AsSpan();
        const string marker = "class=\"result__snippet\">";

        int pos = 0;
        while (results.Count < 5)
        {
            int idx = html.IndexOf(marker, pos, StringComparison.Ordinal);
            if (idx < 0) break;

            int start = idx + marker.Length;
            int end = html.IndexOf('<', start);
            if (end < 0) break;

            var snippet = html[start..end].Trim();
            if (snippet.Length > 0)
                results.Add($"- {System.Net.WebUtility.HtmlDecode(snippet)}");

            pos = end;
        }

        return string.Join("\n", results);
    }
}

