using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

const string modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. When given a topic:
        1. Use the WebSearch tool to find relevant information (make multiple searches if needed).
        2. Use the TakeNote tool to record key findings as you go.
        3. After gathering enough information, provide a comprehensive summary of your findings.
        Always cite which searches led to your conclusions.
        """,
};

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(tools.WebSearch),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");
Console.Write("> ");

while (Console.ReadLine() is { } input && !input.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.Write("> ");
        continue;
    }

    tools.ClearNotes();

    var history = new List<ChatMessage>
    {
        new(ChatRole.User, $"Research the following topic and provide a summary: {input}"),
    };

    var invokeOptions = new AgentInvokeOptions
    {
        MaximumIterations = 10,
        ChatOptions = chatOptions,
    };

    Console.WriteLine("\nResearching...\n");

    await foreach (var message in agent.InvokeStreamingAsync(history, invokeOptions))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine("\n");

    var notes = tools.GetNotes();
    if (!string.IsNullOrWhiteSpace(notes))
    {
        Console.WriteLine("--- Research Notes ---");
        Console.WriteLine(notes);
        Console.WriteLine("--- End Notes ---\n");
    }

    Console.Write("> ");
}

Console.WriteLine("Goodbye!");

