95. /// <summary>Tools available to the research agent.</summary>
96. public sealed class ResearchTools
97. {
98.     private readonly List<string> _notes = [];
99.     private readonly HttpClient _httpClient = new();
100. 
101.     [Description("Searches the web for the given query and returns a summary of results. Use this to find information about a topic.")]
102.     public async Task<string> WebSearch([Description("The search query")] string query)
103.     {
104.         Console.WriteLine($"  [Tool] Searching: \"{query}\"");
105. 
106.         try
107.         {
108.             var encoded = Uri.EscapeDataString(query);
109.             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
110. 
111.             using var request = new HttpRequestMessage(HttpMethod.Get, url);
112.             request.Headers.UserAgent.ParseAdd("ResearchAgent/1.0");
113. 
114.             var response = await _httpClient.SendAsync(request);
115.             var html = await response.Content.ReadAsStringAsync();
116. 
117.             var results = ParseSearchResults(html);
118.             return results.Length > 0
119.                 ? $"Search results for '{query}':\n{results}"
120.                 : $"No results found for '{query}'.";
121.         }
122.         catch (Exception ex)
123.         {
124.             return $"Search failed for '{query}': {ex.Message}";
125.         }
126.     }
127. 
128.     [Description("Records a research note. Use this to save important findings as you discover them.")]
129.     public string TakeNote([Description("The note content to save")] string note)
130.     {
131.         _notes.Add(note);
132.         Console.WriteLine($"  [Tool] Note saved ({_notes.Count} total)");
133.         return $"Note saved. You have {_notes.Count} note(s) recorded.";
134.     }
135. 
136.     [Description("Retrieves all notes taken during this research session.")]
137.     public string GetNotes()
138.     {
139.         if (_notes.Count == 0)
140.             return "No notes recorded yet.";
141. 
142.         return string.Join("\n\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
143.     }
144. 
145.     public void ClearNotes() => _notes.Clear();
146. 
147.     private static string ParseSearchResults(string html)
148.     {
149.         var results = new List<string>();
150.         var span = html.AsSpan();
151.         const string marker = "class=\"result__snippet\">";
152. 
153.         int pos = 0;
154.         while (results.Count < 5)
155.         {
156.             int idx = html.IndexOf(marker, pos, StringComparison.Ordinal);
157.             if (idx < 0) break;
158. 
159.             int start = idx + marker.Length;
160.             int end = html.IndexOf('<', start);
161.             if (end < 0) break;
162. 
163.             var snippet = html[start..end].Trim();
164.             if (snippet.Length > 0)
165.                 results.Add($"- {System.Net.WebUtility.HtmlDecode(snippet)}");
166. 
167.             pos = end;
168.         }
169. 
170.         return string.Join("\n", results);
171.     }
172. }
